---@class BitConfig
local BitConfig = Class("BitConfig")

function BitConfig:__init()
    self.configs = 0x0000
end

function BitConfig:__delete()
end

function BitConfig:Get(index)
    local flag = 1 << index
    return self.configs & flag ~= 0
end

function BitConfig:Set(index, bValue)
    local flag = 1 << index

    if bValue then
        self.configs = self.configs | flag
    else
        local indexValue = self.configs & flag
        if indexValue ~= 0 then
            self.configs = self.configs ~ flag
        end
    end
end

return BitConfig